        # Simpler: track whether put inserted a new row
        def apply_write2(conn, op, key, val):
            nonlocal_committed = committed
            if op == "put":
                existed = key in committed
                if put_mode == "ignore":
                    if existed:
                        return 0, 0
                    committed[key] = val
                    return 1, 1  # direct, trigger
                elif put_mode == "replace":
                    committed[key] = val
                    return 1, 1
                else:  # upsert
                    committed[key] = val
                    if existed:
                        return 1, 0
                    return 1, 1
            elif op == "update":
                if key in committed:
                    committed[key] = val
                    return 1, 0
                return 0, 0
            elif op == "delete":
                if key in committed:
                    del committed[key]
                    return 1, 0
                return 0, 0
            return 0, 0

        for (op, conn, key, val) in actions:
            if op == "begin":
                in_tx[conn] = True
                pending[conn] = []
            elif op == "commit":
                for (wop, wkey, wval) in pending[conn]:
                    d, t = apply_write2(conn, wop, wkey, wval)
                    changes[conn] += d
                    total[conn] += d + t
                pending[conn] = []
                in_tx[conn] = False
            elif op == "rollback":
                pending[conn] = []
                in_tx[conn] = False
            elif op in ("put", "update", "delete"):
                if in_tx[conn]:
                    pending[conn].append((op, key, val))
                else:
                    d, t = apply_write2(conn, op, key, val)
                    changes[conn] += d
                    total[conn] += d + t

        if channel_mode == "changes":
            return changes["main"]
        elif channel_mode == "total_main":
            return total["main"]
        else:
            return total["main"] + total["other"]

    # Enumerate family members
    put_modes = ["ignore", "replace", "upsert"]
    trigs = ["none", "insert"]
    channel_modes = ["changes", "total_main", "total_both"]

    candidates = []
