        last_ch = {'main': 0, 'other': 0}

        def do_write(conn, key, val, mode):
            work = tx[conn] if tx[conn] is not None else db
            changed = 0
            trig_fired = 0
            if mode == 'put':
                if key in work:
                    if put_mode == 'ignore':
                        changed = 0
                    elif put_mode == 'replace':
                        work[key] = val
                        changed = 1
                        trig_fired = 1
                    else:
                        work[key] = val
                        changed = 1
                        trig_fired = 0
                else:
                    work[key] = val
                    changed = 1
                    trig_fired = 1
            else:
                if key in work:
                    work[key] = val
                    changed = 1
