        total_main = 0
        total_other = 0
        last_changes_main = 0

        def eff(conn):
            tx = main_tx if conn == 'main' else other_tx
            if tx is None:
                return dict(committed)
            e = dict(committed)
            for k, v in tx.items():
                if v is None:
                    if k in e:
                        del e[k]
                else:
                    e[k] = v
            return e

        def write(conn, key, value, is_delete):
            nonlocal committed, main_tx, other_tx, total_main, total_other, last_changes_main
            if conn == 'main':
                if main_tx is not None:
                    main_tx[key] = None if is_delete else value
                else:
                    if is_delete:
                        if key in committed:
                            del committed[key]
                    else:
                        committed[key] = value
            else:
                if other_tx is not None:
                    other_tx[key] = None if is_delete else value
                else:
                    if is_delete:
                        if key in committed:
                            del committed[key]
                    else:
                        committed[key] = value

        def count(conn, n):
