                            count(conn, 1)
                else:
                    write(conn, key, value, False)
                    count(conn, 1)
                    if trigger:
                        count(conn, 1)
            elif op == 'update':
                key = action['key']
                value = action['value']
                e = eff(conn)
                if key in e:
                    write(conn, key, value, False)
                    count(conn, 1)
                else:
                    count(conn, 0)
            elif op == 'delete':
                key = action['key']
                e = eff(conn)
                if key in e:
                    write(conn, key, None, True)
                    count(conn, 1)
                else:
                    count(conn, 0)
            elif op == 'begin':
                if conn == 'main':
                    main_tx = {}
                else:
                    other_tx = {}
